<template> <ion-page> <ion-header> <ion-toolbar> <ion-buttons slot="start"> <ion-back-button default-href="/settings"></ion-back-button> </ion-buttons> <ion-title>Security & Privacy</ion-title> </ion-toolbar> </ion-header> <ion-content :fullscreen="true"> <ion-list> <ion-item> <ion-label>Two-Factor Authentication</ion-label> <ion-toggle v-model="security.twoFactorEnabled" @ionChange="updateSecurity"></ion-toggle> </ion-item> <ion-item> <ion-label>Biometric Authentication</ion-label> <ion-toggle v-model="security.biometricEnabled" @ionChange="updateSecurity"></ion-toggle> </ion-item> <ion-item> <ion-label>Private Mode</ion-label> <ion-toggle v-model="security.privateMode" @ionChange="updateSecurity"></ion-toggle> </ion-item> </ion-list> <ion-toast :is-open="toast.isOpen" :message="toast.message" :duration="2000" @didDismiss="toast.isOpen = false" ></ion-toast> </ion-content> </ion-page> </template> <script lang="ts"> import { defineComponent, ref, onMounted } from 'vue'; import { IonPage, IonHeader, IonToolbar, IonButtons, IonBackButton, IonTitle, IonContent, IonList, IonItem, IonLabel, IonToggle, IonToast, } from '@ionic/vue'; import api from '../services/api'; import { SecuritySettings } from '../types/settings'; export default defineComponent({ name: 'SecuritySettings', components: { IonPage, IonHeader, IonToolbar, IonButtons, IonBackButton, IonTitle, IonContent, IonList, IonItem, IonLabel, IonToggle, IonToast }, setup() { const security = ref<SecuritySettings>({ twoFactorEnabled: false, biometricEnabled: false, privateMode: false }); const toast = ref({ isOpen: false, message: '' }); const fetchSecurity = async () => { try { const response = await api.get('/user/security'); security.value = response.data; } catch (error) { toast.value = { isOpen: true, message: 'Failed to load security settings' }; } }; const updateSecurity = async () => { try { await api.post('/user/security', security.value); toast.value = { isOpen: true, message: 'Security settings updated' }; } catch (error) { toast.value = { isOpen: true, message: 'Failed to update security settings' }; } }; onMounted(fetchSecurity); return { security, toast, updateSecurity }; }, }); </script>